// n8n's error trigger already knows which node broke: err.node.name, or
// lastNodeExecuted when the failure happened outside a node. That is exactly
// the field the collector counts failures by, so pass it through unchanged.
const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const err = execution.error ?? {};
const node = err.node?.name ?? execution.lastNodeExecuted ?? null;

// n8n reports HTTP codes as strings ('503'); the collector wants a number, and
// uses it to classify the failure (429 rate limited, 503 overloaded, ...).
const httpStatus = Number(err.httpCode ?? err.status ?? NaN);
const message = [err.message, err.description]
  .filter(Boolean)
  .join(' - ')
  .slice(0, 500);

return {
  json: {
    // One id per execution, so a retried alert is not counted twice.
    run_id: `n8n-${execution.id ?? Date.now()}`,
    workflow: workflow.name ?? 'unknown',
    status: 'failed',
    started_at: Math.floor(Date.now() / 1000),
    failed_node: node,
    error: message,
    steps: node
      ? [{
          node,
          status: 'failed',
          ...(Number.isFinite(httpStatus) ? { http_status: httpStatus } : {}),
          error: message,
        }]
      : [],
    attrs: {
      execution_id: String(execution.id ?? ''),
      execution_url: execution.url ?? '',
      mode: execution.mode ?? '',
      retry_of: String(execution.retryOf ?? ''),
    },
  },
};
